// Validates the files generated by `npm run data`. If one of these fails, fix the script or
// scripts/decisions.json and regenerate; never edit public/data by hand.
import brazilTopo from '../../../../public/data/brazil.topo.json';
import countriesJson from '../../../../public/data/countries.json';
import regionsJson from '../../../../public/data/regions-br.json';
import statesJson from '../../../../public/data/states.json';
import territoriesJson from '../../../../public/data/territories.json';
import worldTopo from '../../../../public/data/world.topo.json';
import { geoBounds, geoContains } from 'd3-geo';
import type { Feature, Geometry, Position } from 'geojson';
import { feature } from 'topojson-client';
import type { GeometryCollection, Topology } from 'topojson-specification';
import {
  BrazilRegion,
  BrazilState,
  Continent,
  Country,
  LonLat,
  Territory,
  WorldUnitProperties,
} from './geo-data.models';

// JSON imports type tuples as number[], hence the cast through unknown.
const countries = countriesJson as unknown as Country[];
const territories = territoriesJson as unknown as Territory[];
const states = statesJson as unknown as BrazilState[];
const regions = regionsJson as BrazilRegion[];
const units = worldTopo.objects.units.geometries.map((g) => g.properties as WorldUnitProperties);

function decode(topology: unknown, object: string): Map<string, Feature<Geometry>> {
  const topo = topology as Topology<Record<string, GeometryCollection>>;
  const collection = feature(topo, topo.objects[object]);
  return new Map(collection.features.map((f) => [String(f.id), f]));
}
const worldShapes = decode(worldTopo, 'units');
const brazilShapes = decode(brazilTopo, 'states');

/** True when at least one ring still has 3 distinct points after simplification. */
function hasVisibleShape(shape: Feature<Geometry>): boolean {
  const geometry = shape.geometry;
  const polygons: Position[][][] =
    geometry.type === 'Polygon'
      ? [geometry.coordinates]
      : geometry.type === 'MultiPolygon'
        ? geometry.coordinates
        : [];
  return polygons.some((rings) => new Set(rings[0].map((p) => p.join(','))).size >= 3);
}

/** True when the point is inside the shape's bounding box (1° of slack, antimeridian-safe). */
function isNear(point: LonLat, shape: Feature<Geometry>): boolean {
  const [[west, south], [east, north]] = geoBounds(shape);
  const [lon, lat] = point;
  const inLon =
    west <= east ? lon >= west - 1 && lon <= east + 1 : lon >= west - 1 || lon <= east + 1;
  return inLon && lat >= south - 1 && lat <= north + 1;
}

const CONTINENTS: Continent[] = [
  'africa',
  'antarctica',
  'asia',
  'europe',
  'north-america',
  'oceania',
  'south-america',
];
const countryIds = new Set(countries.map((c) => c.id));

function expectCompletePlace(place: Country | Territory | BrazilState) {
  expect(place.name.pt.trim(), place.id).not.toBe('');
  expect(place.name.en.trim(), place.id).not.toBe('');
  expect(place.areaKm2, place.id).toBeGreaterThan(0);
  expect(place.flag, place.id).toMatch(/^flags\/(world|br)\/[a-z]+\.svg$/);
  for (const capital of place.capitals) {
    expect(capital.name.pt.trim(), place.id).not.toBe('');
    expect(capital.name.en.trim(), place.id).not.toBe('');
  }
}

describe('countries.json', () => {
  it('has the 193 UN members plus Vatican and Palestine', () => {
    expect(countries.length).toBe(195);
    expect(countryIds.size).toBe(195);
    expect(countryIds.has('VAT')).toBe(true);
    expect(countryIds.has('PSE')).toBe(true);
  });

  it('gives every country codes, names, capital, flag, continent and area', () => {
    for (const country of countries) {
      expect(country.id).toMatch(/^[A-Z]{3}$/);
      expect(country.iso2).toMatch(/^[A-Z]{2}$/);
      expect(country.capitals.length, country.id).toBeGreaterThan(0);
      expect(CONTINENTS, country.id).toContain(country.continent);
      expectCompletePlace(country);
    }
  });

  it('keeps every capital of countries with more than one (Bolivia, South Africa)', () => {
    const capitalsOf = (id: string) =>
      countries.find((c) => c.id === id)!.capitals.map((c) => c.name.en);
    expect(capitalsOf('BOL')).toEqual(expect.arrayContaining(['Sucre', 'La Paz']));
    expect(capitalsOf('ZAF').length).toBe(3);
  });

  it('gives Yemen only Sana as capital (author decision)', () => {
    const capitals = countries.find((c) => c.id === 'YEM')!.capitals.map((c) => c.name.en);
    expect(capitals.length).toBe(1);
    expect(capitals).not.toContain('Aden');
  });

  it('has unique primary names in each language, also counting territories', () => {
    for (const lang of ['pt', 'en'] as const) {
      const names = [...countries, ...territories].map((c) => c.name[lang].toLowerCase());
      expect(new Set(names).size, lang).toBe(names.length);
    }
  });
});

describe('territories.json', () => {
  it('lists territories that are not countries, administered by a country or by none', () => {
    expect(territories.length).toBeGreaterThan(0);
    for (const territory of territories) {
      expect(countryIds.has(territory.id), territory.id).toBe(false);
      if (territory.administeredBy !== null) {
        expect(countryIds.has(territory.administeredBy), territory.id).toBe(true);
      }
      expectCompletePlace(territory);
    }
  });

  it('names every claimant and only links real countries', () => {
    for (const place of [...countries, ...territories]) {
      for (const claimant of place.claimedBy) {
        expect(claimant.name.pt.trim(), place.id).not.toBe('');
        if (claimant.country !== null)
          expect(countryIds.has(claimant.country), place.id).toBe(true);
      }
    }
  });

  it('explains the status of every territory without an administering country', () => {
    const orphans = territories.filter((t) => t.administeredBy === null);
    expect(orphans.map((t) => t.id)).toEqual(
      expect.arrayContaining(['ATA', 'CYN', 'ESH', 'KOS', 'SOL', 'TWN']),
    );
    for (const territory of orphans) expect(territory.statusNote?.pt, territory.id).toBeTruthy();
  });
});

describe('world.topo.json and the territories rule', () => {
  it('gives every country and territory a shape or a clickable point on the map', () => {
    for (const place of [...countries, ...territories]) {
      const shape = worldShapes.get(place.id);
      expect(shape, place.id).toBeDefined();
      // The label point is the fallback click target for places too small to see.
      const [lon, lat] = place.labelPoint;
      expect(Math.abs(lon) <= 180 && Math.abs(lat) <= 90, place.id).toBe(true);
      expect(hasVisibleShape(shape!) || isNear(place.labelPoint, shape!), place.id).toBe(true);
      expect(isNear(place.labelPoint, shape!), `${place.id}: ponto longe da forma`).toBe(true);
    }
  });

  it('keeps tiny island countries on the map', () => {
    for (const id of ['TUV', 'NRU', 'MDV', 'MHL', 'VAT', 'MCO']) {
      const shape = worldShapes.get(id)!;
      expect(shape, id).toBeDefined();
      const place = countries.find((c) => c.id === id)!;
      expect(hasVisibleShape(shape) || isNear(place.labelPoint, shape), id).toBe(true);
    }
  });

  it('treats Western Sahara like the self-governing places, not as Morocco', () => {
    const westernSahara = units.find((u) => u.id === 'ESH')!;
    expect(westernSahara.country).toBeNull();
    expect(westernSahara.territory).toBe('ESH');
  });

  it('with territories off, the targets are exactly the 195 countries', () => {
    const targets = new Set(units.map((u) => u.country).filter((id) => id !== null));
    expect(targets).toEqual(countryIds);

    const greenland = units.find((u) => u.id === 'GRL')!;
    expect(greenland.country).toBe('DNK');
    const antarctica = units.find((u) => u.id === 'ATA')!;
    expect(antarctica.country).toBeNull();
  });

  it('with territories on, territories become targets of their own and the total passes 195', () => {
    const targets = new Set(units.map((u) => u.territory ?? u.country).filter((id) => id !== null));
    expect(targets.size).toBe(195 + territories.length);
    expect(targets.has('ATA')).toBe(true);
    expect(targets.has('GRL')).toBe(true);
  });
});

describe('Brazil data', () => {
  it('has the 26 states plus the Federal District', () => {
    expect(states.length).toBe(27);
    expect(new Set(states.map((s) => s.id)).size).toBe(27);
    expect(states.some((s) => s.id === 'DF')).toBe(true);
  });

  it('gives every state one capital, a region, a flag and an area', () => {
    const regionIds = new Set(regions.map((r) => r.id));
    expect(regionIds.size).toBe(5);
    for (const state of states) {
      expect(state.id).toMatch(/^[A-Z]{2}$/);
      expect(state.capitals.length, state.id).toBe(1);
      expect(regionIds.has(state.region), state.id).toBe(true);
      expectCompletePlace(state);
    }
  });

  it('has a shape for every state, with its label point inside it', () => {
    expect(new Set(brazilShapes.keys())).toEqual(new Set(states.map((s) => s.id)));
    for (const state of states) {
      expect(geoContains(brazilShapes.get(state.id)!, state.labelPoint), state.id).toBe(true);
    }
  });
});
